import {distanceMiles,summary,validateEnd} from './model.js';

const KEY='cab-ledger-v1';
const defaults={cab:{type:'Diesel',rate:0.25,fixed:0},active:null,shifts:[]};
let state;
try{state={...defaults,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state=structuredClone(defaults)}
let gpsWatch=null,lastPoint=null,modalAction=null;
const $=id=>document.getElementById(id);
const money=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(n||0);
const fmtDate=ms=>new Intl.DateTimeFormat('en-GB',{dateStyle:'medium'}).format(ms);
const fmtTime=ms=>new Intl.DateTimeFormat('en-GB',{hour:'2-digit',minute:'2-digit'}).format(ms);
const fixed=n=>(n||0).toFixed(1);
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{notice('This browser cannot save shifts. Check that storage is enabled before continuing.');return false}}
function notice(message){$('notice').textContent=message;$('notice').hidden=!message}
function openModal(title,fields,action,button='Save'){$('modal-title').textContent=title;$('modal-fields').innerHTML=fields;$('submit-modal').textContent=button;$('form-error').textContent='';modalAction=action;$('modal').showModal()}
function field(label,name,value='',step='0.01',min='0'){return `<label class="field">${label}<input name="${name}" type="number" inputmode="decimal" min="${min}" step="${step}" value="${value}" required></label>`}
function select(label,name,options,current){return `<label class="field">${label}<select name="${name}">${options.map(x=>`<option${x===current?' selected':''}>${x}</option>`).join('')}</select></label>`}
function validMoney(n){return Number.isFinite(n)&&n>=0}
function showCab(){openModal('Your cab',select('Vehicle','type',['Diesel','Electric','Hybrid / other'],state.cab.type)+field('Estimated fuel or electricity cost per mile (£)','rate',state.cab.rate,'0.01')+field('Fixed cost per shift (£)','fixed',state.cab.fixed,'0.01')+'<p class="help">Use your own estimates. You can change these for future shifts.</p>',data=>{const rate=Number(data.get('rate')),fixedCost=Number(data.get('fixed'));if(!validMoney(rate)||!validMoney(fixedCost))return 'Enter valid costs of £0 or more.';state.cab={type:data.get('type'),rate,fixed:fixedCost};return persist()?null:'Unable to save your cab details.'})}
function showStart(){openModal('Start a shift',field('Starting odometer (miles)','startOdo','','1')+'<p class="help">Your odometer is the most reliable way to confirm total miles. You can still record jobs without location.</p>',data=>{const odo=Number(data.get('startOdo'));if(!Number.isFinite(odo)||odo<0)return 'Enter a valid starting mileage.';state.active={id:crypto.randomUUID(),start:Date.now(),startOdo:odo,cab:{...state.cab},gpsMiles:0,jobs:[],jobStart:null};return persist()?null:'Unable to save this shift.'},'Start shift')}
function showJobEnd(){const s=state.active;openModal('Finish this job',field('Fare received (£)','fare','','0.01')+'<p class="help">Leave this as £0 if you will enter your total takings at the end of the shift.</p>',data=>{const fare=Number(data.get('fare'));if(!validMoney(fare))return 'Enter a valid fare of £0 or more.';s.jobs.push({start:s.jobStart,end:Date.now(),fare});s.jobStart=null;return persist()?null:'Unable to save this job.'},'Save job')}
function showEnd(){const s=state.active;openModal('End shift',field('Ending odometer (miles)','endOdo','','1',String(s.startOdo))+field('Total takings (£)','income',s.jobs.reduce((n,j)=>n+j.fare,0).toFixed(2))+field('Other shift expenses (£)','extra','0')+field('Break time (minutes)','breakMinutes','0','1')+'<p class="help">Total takings should include any fares you recorded. Your end mileage confirms the shift distance.</p>',data=>{const values=Object.fromEntries(['endOdo','income','extra','breakMinutes'].map(k=>[k,Number(data.get(k))]));const error=validateEnd(s,values);if(error)return error;s.end=Date.now();Object.assign(s,values);s.jobStart=null;state.shifts.unshift(s);state.active=null;stopGps();return persist()?null:'Unable to save the completed shift.'},'Finish shift')}
function stopGps(){if(gpsWatch!==null)navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null;lastPoint=null}
function gpsError(error){const message=error?.code===1?'Location permission was denied. Your shift can still be completed with odometer readings.':'Location is unavailable right now. Use your odometer to confirm the total.';stopGps();notice(message);render()}
function enableGps(){if(!state.active)return;if(!navigator.geolocation){notice('Location is unavailable in this browser.');return}if(gpsWatch!==null){stopGps();render();return}notice('');gpsWatch=navigator.geolocation.watchPosition(pos=>{if(!state.active){stopGps();return}const point={lat:pos.coords.latitude,lon:pos.coords.longitude,time:pos.timestamp,accuracy:pos.coords.accuracy};if(lastPoint&&point.accuracy<=75&&lastPoint.accuracy<=75&&point.time>lastPoint.time){const miles=distanceMiles(lastPoint,point),hours=(point.time-lastPoint.time)/3600000;if(miles>=0.01&&miles<0.5&&hours<0.15&&miles/hours<100){state.active.gpsMiles+=miles;persist();render()}}lastPoint=point;},gpsError,{enableHighAccuracy:true,maximumAge:0,timeout:15000});render()}
document.addEventListener('visibilitychange',()=>{if(document.hidden)lastPoint=null});
function render(){const active=state.active,s=active||state.shifts[0],v=summary(s);$('today').textContent=new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(Date.now()).toUpperCase();$('shift-state').textContent=active?'SHIFT IN PROGRESS':'OFF THE CLOCK';$('shift-title').textContent=active?`Started ${fmtTime(active.start)}`:'Ready when you are.';$('shift-description').textContent=active?`Odometer at start: ${active.startOdo.toLocaleString('en-GB')} miles. ${active.jobs.length} job${active.jobs.length===1?'':'s'} logged.`:'Start a shift to keep your time, miles and takings together.';$('start').hidden=!!active;$('job').hidden=!active;$('job').textContent=active?.jobStart?'End job':'Start job';$('finish').hidden=!active;$('active-tools').hidden=!active;$('gps-status').textContent=gpsWatch===null?'Location is off':'Location is on · distance estimate '+fixed(active?.gpsMiles)+' mi';$('gps').textContent=gpsWatch===null?'Enable location':'Stop location';$('summary-title').textContent=active?'Current shift':'Your latest shift';$('summary-date').textContent=s?fmtDate(s.start):'No shifts yet';$('income').textContent=money(v.income);$('distance').innerHTML=`${fixed(v.miles)} <small>mi</small>`;$('distance-caption').textContent=active?'GPS estimate · confirm with odometer':'Confirmed from odometer';$('costs').textContent=money(v.cost);$('remaining').textContent=money(v.remaining);$('hourly').textContent=s?`${money(v.hourly)} per working hour · before tax`:'Before tax and unrecorded costs';$('cab-type').textContent=state.cab.type+' cab';$('cab-rate').textContent=money(state.cab.rate);$('cab-fixed').textContent=money(state.cab.fixed)+' fixed cost per shift';$('history').innerHTML=state.shifts.length?state.shifts.map((x,i)=>{const z=summary(x);return `<div class="history-row"><div><strong>${fmtDate(x.start)}</strong><p>${fmtTime(x.start)}–${fmtTime(x.end)} · ${fixed(z.miles)} mi · ${x.jobs.length} jobs</p><button class="delete" data-delete="${i}" aria-label="Delete shift from ${fmtDate(x.start)}">Delete</button></div><div class="amount"><strong>${money(z.remaining)}</strong><p>${money(z.income)} takings</p></div></div>`}).join(''):'<div class="empty"><strong>No shifts yet</strong>Your completed shifts will appear here.</div>';$('export').disabled=!state.shifts.length;$('jobs-section').hidden=!active;$('jobs').innerHTML=active?active.jobs.length?active.jobs.map(j=>`<div class="history-row"><div><strong>${fmtTime(j.start)}–${fmtTime(j.end)}</strong><p>Recorded job</p></div><strong>${money(j.fare)}</strong></div>`).join(''):'<div class="empty">No jobs recorded yet.</div>':''}
$('settings').onclick=$('edit-cab').onclick=showCab;$('start').onclick=showStart;$('finish').onclick=showEnd;$('gps').onclick=enableGps;$('job').onclick=()=>{const s=state.active;if(!s)return;if(s.jobStart)showJobEnd();else{s.jobStart=Date.now();persist();render()}};$('close-modal').onclick=()=>$('modal').close();$('modal-form').onsubmit=e=>{e.preventDefault();const error=modalAction(new FormData(e.currentTarget));if(error){$('form-error').textContent=error;return}$('modal').close();notice('');render()};$('history').onclick=e=>{const button=e.target.closest('[data-delete]');if(!button)return;const i=Number(button.dataset.delete);if(confirm('Delete this shift permanently from this device?')){state.shifts.splice(i,1);persist();render()}};
$('export').onclick=()=>{const rows=[['Date','Start','End','Vehicle','Starting odometer','Ending odometer','Miles','Fare income GBP','Estimated costs GBP','After costs GBP','Working hours','Jobs'],...state.shifts.map(s=>{const x=summary(s);return [fmtDate(s.start),fmtTime(s.start),fmtTime(s.end),s.cab.type,s.startOdo,s.endOdo,x.miles.toFixed(2),x.income.toFixed(2),x.cost.toFixed(2),x.remaining.toFixed(2),x.hours.toFixed(2),s.jobs.length]})];const csv=rows.map(row=>row.map(value=>'"'+String(value??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='cab-ledger-shifts.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_shift_summary',title:'Read shift summary',description:'Read the current or latest cab shift summary stored in this browser.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){const s=state.active||state.shifts[0];if(!s)return {status:'no_shifts'};return {status:state.active?'active':'completed',...summary(s)}}})}catch{}}
render();
